# frozen_string_literal: true

module CalmLens
  # CDN transform selectors: selector Strings and structured options serialized the way every SDK does.
  # @api private
  module Transforms
    module_function

    OPTION_NAME = /\A[a-z][a-zA-Z0-9]*\z/
    # <generated: image-transform-colours>
    # Generated by packages/sdk-contract/generate.ts from IMAGE_TRANSFORM_OPTIONS_SCHEMA; do not edit.
    # Options that hold colours, written as hex without `#` in a selector.
    COLOUR_KEYS = %w[background border.color trim.border.color].freeze
    # </generated: image-transform-colours>
    HEX_COLOUR = /\A#((?:\h{3}){1,2}|(?:\h{4}){1,2})\z/

    # Returns the selector the API and CDN accept for a transform: a selector String checked and
    # unchanged, or structured options (`{width: 640, fit: 'cover'}`) serialized by {serialize}.
    def selector(value)
      return serialize(value) unless value.nil? || value.is_a?(String)
      # A transform is one path segment of options: it must not add a segment, lens, query or fragment.
      if value&.match?(%r{[/?#]}) || value&.include?('..') || value&.start_with?('@')
        raise Internal.invalid('Transform cannot contain "/", "..", "?" or "#", or start with "@"')
      end

      value
    end

    # Builds the CDN path text of a transform. A selector String is encoded like JavaScript's
    # encodeURI; serialized options are already path-safe.
    def path(value)
      text = selector(value)
      return text unless value.is_a?(String)

      # Like JavaScript's encodeURI.
      text.b.gsub(%r{[^A-Za-z0-9\-_.!~*'();/:@&=+$,]}n) { |byte| format('%%%02X', byte.ord) }
    end

    # Serializes structured transform options as a CDN selector, such as `fit=cover,width=640`. Option
    # keys are sorted so equal transforms share a URL, nested keys are dotted (`border.color`), hex
    # colours are written without `#` and values are percent-encoded.
    def serialize(value)
      raise Internal.invalid('Transform options must be a Hash') unless value.is_a?(Hash)

      pairs = []
      sorted_options(value).each { |key, item| append_pairs(pairs, key, item) }
      raise Internal.invalid('A transform needs at least one option') if pairs.empty?

      pairs.join(',')
    end

    def sorted_options(options, prefix = '')
      options.map do |key, item|
        name = key.to_s
        raise Internal.invalid("Transform option \"#{prefix}#{name}\" is not a valid name") unless name.match?(OPTION_NAME)

        [name, item]
      end.sort_by(&:first)
    end

    def append_pairs(pairs, key, value)
      return if value.nil?
      return sorted_options(value, "#{key}.").each { |child, item| append_pairs(pairs, "#{key}.#{child}", item) } if value.is_a?(Hash)

      text = case value
             when String then colour(key, value)
             when true, false, Integer then value.to_s
             when Float
               raise Internal.invalid("Transform option \"#{key}\" must be a finite number") unless value.finite?

               js_number(value)
             else raise Internal.invalid("Transform option \"#{key}\" must be a String, number, boolean or Hash")
             end
      pairs << "#{key}=#{component(text)}"
    end

    # Writes a hex colour option without `#`, in lower case; other values are unchanged.
    def colour(key, value)
      match = COLOUR_KEYS.include?(key) && HEX_COLOUR.match(value)
      match ? match[1].downcase : value
    end

    # Percent-encodes everything except RFC 3986 unreserved characters.
    def component(text)
      text.encode(Encoding::UTF_8).b.gsub(/[^A-Za-z0-9\-._~]/n) { |byte| format('%%%02X', byte.ord) }
    end

    # Formats a Float the way JavaScript's String(number) does, so every SDK builds the same URL.
    def js_number(value)
      return '0' if value.zero?

      mantissa, exponent = value.abs.to_s.split('e')
      whole, fraction = mantissa.split('.')
      digits = "#{whole}#{fraction}"
      point = whole.length + exponent.to_i
      stripped = digits.sub(/\A0+/, '')
      point -= digits.length - stripped.length
      digits = stripped.sub(/0+\z/, '')
      sign = value.negative? ? '-' : ''
      "#{sign}#{js_digits(digits, point)}"
    end

    # Places a decimal point in significant `digits` whose value is 0.digits x 10^point.
    def js_digits(digits, point)
      size = digits.length
      if point.between?(size, 21) then digits + ('0' * (point - size))
      elsif point.positive? && point <= 21 then "#{digits[0, point]}.#{digits[point..]}"
      elsif point > -6 && point <= 0 then "0.#{'0' * -point}#{digits}"
      else
        shown = size > 1 ? "#{digits[0]}.#{digits[1..]}" : digits
        "#{shown}e#{point - 1 >= 0 ? '+' : '-'}#{(point - 1).abs}"
      end
    end
  end
  private_constant :Transforms
end
